def rule_statutory_debt_limit_amount(doc: dict) -> list[dict]:
    try:
        import re

        lines = doc.get("lines") or []
        paragraphs = doc.get("paragraphs") or []
        spans = []
        seen = set()

        key_re = re.compile(
            r"(statutory debt limit|debt subject to statutory limit|debt subject to statutory limitation|balance of statutory debt limit|status under limitation|application of statutory limitation|debt ceiling|table fd-6|table ii:\s*statutory debt limit)",
            re.I,
        )
        amount_re = re.compile(r"(\$?\d[\d,]*(?:\.\d+)?(?:\s*(?:million|billion|trillion))?)", re.I)
        break_re = re.compile(
            r"^(?:table fd-7|table fd-8|table fd-9|table fd-10|public debt operations|federal debt|footnotes?|part b\.|bureau of the fiscal service|analysis|table ii:|table fd-7[—\.\-])",
            re.I,
        )
        tail_markers = re.compile(r"(permanently increased|statutory debt limit|balance of statutory debt limit|debt subject to limit|suspended)", re.I)

        def add_span(text: str, meta: dict) -> None:
            text = (text or "").strip()
            if not text:
                return
            key = (
                meta.get("page_no"),
                meta.get("line_no"),
                meta.get("paragraph_no"),
                text,
            )
            if key in seen:
                return
            seen.add(key)
            span = dict(meta)
            span["text"] = text
            spans.append(span)

        def line_window(idx: int, before: int = 2, after: int = 4) -> str:
            start = max(0, idx - before)
            end = min(len(lines), idx + after + 1)
            chunk = []
            for item in lines[start:end]:
                item_text = (item.get("text") or "").rstrip()
                if item_text:
                    chunk.append(item_text)
            return "\n".join(chunk)

        def table_tail(idx: int) -> str:
            start = idx
            end = len(lines)
            for j in range(idx + 1, len(lines)):
                nxt = (lines[j].get("text") or "").strip()
                if j > idx + 6 and break_re.search(nxt):
                    end = j
                    break
            block = lines[start:end]
            block_texts = [(item.get("text") or "").rstrip() for item in block if (item.get("text") or "").strip()]
            if len(block_texts) > 18:
                block_texts = block_texts[-18:]
            return "\n".join(block_texts)

        # Paragraph-level exact hits.
        for para in paragraphs:
            text = (para.get("text") or "").strip()
            lo = text.lower()
            if not text or not key_re.search(text):
                continue
            if amount_re.search(text) or "permanently increased" in lo:
                add_span(
                    text,
                    {
                        "page_no": para.get("page_no"),
                        "paragraph_no": para.get("paragraph_no"),
                    },
                )

        # Line-level hits and table-tail extraction.
        for idx, line in enumerate(lines):
            text = (line.get("text") or "").strip()
            lo = text.lower()
            if not text:
                continue

            if "table fd-6" in lo or "part a. - status under limitation" in lo or "part a.—status under limitation" in lo:
                snippet = table_tail(idx)
                if snippet and tail_markers.search(snippet):
                    add_span(
                        snippet,
                        {
                            "page_no": line.get("page_no"),
                            "line_no": line.get("line_no"),
                        },
                    )
                continue

            if key_re.search(text) and (amount_re.search(text) or "permanently increased" in lo):
                add_span(
                    line_window(idx),
                    {
                        "page_no": line.get("page_no"),
                        "line_no": line.get("line_no"),
                    },
                )
                continue

            if "statutory debt limit" in lo and idx + 1 < len(lines):
                nxt = (lines[idx + 1].get("text") or "").strip()
                if amount_re.search(nxt):
                    add_span(
                        line_window(idx, before=1, after=2),
                        {
                            "page_no": line.get("page_no"),
                            "line_no": line.get("line_no"),
                        },
                    )
                    continue

            if "balance of statutory debt limit" in lo or "debt subject to statutory limit" in lo or "debt subject to statutory limitation" in lo:
                add_span(
                    line_window(idx),
                    {
                        "page_no": line.get("page_no"),
                        "line_no": line.get("line_no"),
                    },
                )

        return spans[:6]
    except Exception:
        return []

def rule_statutory_debt_limit_suspended(doc: dict) -> list[dict]:
